    public List<String> readBinaryWatch(int turnedOn) {
        List<String> res = new ArrayList<>();
        int[] weights = {8, 4, 2, 1, 32, 16, 8, 4, 2, 1};
        dfs(0, turnedOn, 0, 0, weights, res);
        return res;
    }
    private void dfs(int idx, int count, int h, int m, int[] weights, List<String> res) {
        if (h > 11 || m > 59) return;
        if (count == 0) {
            res.add(String.format("%d:%02d", h, m));
            return;
        }
        for (int i = idx; i < weights.length; i++) {
            if (i < 4) dfs(i + 1, count - 1, h + weights[i], m, weights, res);
            else dfs(i + 1, count - 1, h, m + weights[i], weights, res);
        }
    }
}

