        def permute(start: int) -> None:
            nonlocal count
            if start == n:
                count += 1
                return
            for i in range(start, n):
                nums[start], nums[i] = nums[i], nums[start]
                pos = start + 1
                if nums[start] % pos == 0 or pos % nums[start] == 0:
                    permute(start + 1)
                nums[start], nums[i] = nums[i], nums[start]
        permute(0)
        return count

