class Solution {
    private int maxLen = 0;
    public int maxLength(List<String> arr) {
        List<Integer> masks = new ArrayList<>();
        for (String s : arr) {
            int m = 0;
            boolean ok = true;
            for (char c : s.toCharArray()) {
                int bit = 1 << (c - 'a');
                if ((m & bit) != 0) { ok = false; break; }
                m |= bit;
            }
            if (ok) masks.add(m);
        }
        backtrack(0, 0, masks);
        return maxLen;
    }
    private void backtrack(int idx, int mask, List<Integer> masks) {
        maxLen = Math.max(maxLen, Integer.bitCount(mask));
        for (int i = idx; i < masks.size(); i++) {
            int nextMask = masks.get(i);
            if ((mask & nextMask) == 0) {
                backtrack(i + 1, mask | nextMask, masks);
            }
        }
    }
}

