class Solution {
    public int countNumbersWithUniqueDigits(int n) {
        if (n == 0) return 1;
        int limit = (int) Math.pow(10, Math.min(n, 4));
        int count = 0;
        for (int i = 0; i < limit; i++) {
            if (hasUniqueDigits(i)) count++;
        }
        return count;
    }
    private boolean hasUniqueDigits(int num) {
        int mask = 0;
        if (num == 0) return true;
        while (num > 0) {
            int d = num % 10;
            if ((mask & (1 << d)) != 0) return false;
            mask |= (1 << d);
            num /= 10;
        }
        return true;
    }
}

