                return 0
            val = grid[r][c]
            grid[r][c] = 0
            best = max(
                dfs(r + 1, c),
                dfs(r - 1, c),
                dfs(r, c + 1),
                dfs(r, c - 1)
            )
            grid[r][c] = val
            return val + best
