class Solution {
    private int paths = 0;
    public int uniquePathsIII(int[][] grid) {
        int startR = 0, startC = 0, empty = 1;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1) { startR = i; startC = j; }
                else if (grid[i][j] == 0) empty++;
            }
        }
        boolean[][] vis = new boolean[grid.length][grid[0].length];
        dfs(grid, startR, startC, empty, vis);
        return paths;
    }
    private void dfs(int[][] grid, int r, int c, int remain, boolean[][] vis) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == -1 || vis[r][c]) return;
        if (grid[r][c] == 2) {
            if (remain == 0) paths++;
            return;
        }
        vis[r][c] = true;
        dfs(grid, r + 1, c, remain - 1, vis);
        dfs(grid, r - 1, c, remain - 1, vis);
        dfs(grid, r, c + 1, remain - 1, vis);
        dfs(grid, r, c - 1, remain - 1, vis);
        vis[r][c] = false;
    }
}

