    public List<Integer> splitIntoFibonacci(String num) {
        List<Integer> res = new ArrayList<>();
        backtrack(0, num, res);
        return res;
    }
    private boolean backtrack(int idx, String num, List<Integer> res) {
        if (idx == num.length() && res.size() >= 3) return true;
        for (int i = idx; i < num.length(); i++) {
            if (num.charAt(idx) == '0' && i > idx) break;
            long val = Long.parseLong(num.substring(idx, i + 1));
            if (val > Integer.MAX_VALUE) break;
            int sz = res.size();
            if (sz >= 2 && val > (long) res.get(sz - 1) + res.get(sz - 2)) break;
            if (sz < 2 || val == (long) res.get(sz - 1) + res.get(sz - 2)) {
                res.add((int) val);
                if (backtrack(i + 1, num, res)) return true;
                res.remove(res.size() - 1);
            }
        }
        return false;
    }
}

