        for (int i = idx + 1; i <= s.length(); i++) {
            String word = s.substring(idx, i);
            if (dict.contains(word)) {
                int prevLen = sb.length();
                if (prevLen > 0) sb.append(" ");
                sb.append(word);
                backtrack(s, i, sb, dict, res);
                sb.setLength(prevLen);
            }
        }
    }
}

