        List<String> res = new ArrayList<>();
        if (num.isEmpty()) return res;
        dfs(0, num, target, 0, 0, "", res);
        return res;
    }
    private void dfs(int idx, String num, int target, long val, long prev, String expr, List<String> res) {
        if (idx == num.length()) {
            if (val == target) res.add(expr);
            return;
