        for (int i = idx; i < num.length(); i++) {
            if (i > idx && num.charAt(idx) == '0') break;
            String part = num.substring(idx, i + 1);
            long cur = Long.parseLong(part);
            if (idx == 0) {
                dfs(i + 1, num, target, cur, cur, part, res);
            } else {
                dfs(i + 1, num, target, val + cur, cur, expr + "+" + part, res);
                dfs(i + 1, num, target, val - cur, -cur, expr + "-" + part, res);
                dfs(i + 1, num, target, val - prev + prev * cur, prev * cur, expr + "*" + part, res);
            }
        }
    }
