class Solution {
    public List<String> addOperators(String num, int target) {
        List<String> res = new ArrayList<>();
        if (num.isEmpty()) return res;
        StringBuilder sb = new StringBuilder();
        backtrack(0, num, target, 0, 0, sb, res);
        return res;
    }
    private void backtrack(int idx, String num, int target, long val, long prev, StringBuilder sb, List<String> res) {
        if (idx == num.length()) {
            if (val == target) res.add(sb.toString());
            return;
        }
        long cur = 0;
        for (int i = idx; i < num.length(); i++) {
            if (i > idx && num.charAt(idx) == '0') break;
            cur = cur * 10 + (num.charAt(i) - '0');
            int len = sb.length();
            if (idx == 0) {
                sb.append(cur);
                backtrack(i + 1, num, target, cur, cur, sb, res);
                sb.setLength(len);
            } else {
                sb.append('+').append(cur);
                backtrack(i + 1, num, target, val + cur, cur, sb, res);
                sb.setLength(len);

                sb.append('-').append(cur);
                backtrack(i + 1, num, target, val - cur, -cur, sb, res);
                sb.setLength(len);

                sb.append('*').append(cur);
                backtrack(i + 1, num, target, val - prev + prev * cur, prev * cur, sb, res);
                sb.setLength(len);
            }
        }
    }
}
